{
  "items": [
    {
      "item": "i01",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "tradition",
          "detail": "五行相生关系由五行属性确定，不以阴阳为成立条件；阴阳主要用于进一步区分十神等关系。"
        },
        {
          "dimension": "plain_language",
          "detail": "未解释“生”的含义。宜说明其指一行对另一行的生助、滋养关系，如水生木，并将“不能推出喜用神”改为“仅凭这一关系不能判断喜用神”。"
        }
      ],
      "reason": "中性的主题方向合理，但相生的判定条件表述不准，且缺少面向用户的实际释义。"
    },
    {
      "item": "i02",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "tradition",
          "detail": "“耗”不以双方阴阳为成立条件；在以某一五行为参照的生克泄耗关系中，通常指其克制另一五行时自身力量受到耗用。"
        },
        {
          "dimension": "plain_language",
          "detail": "未交代“耗”的参照主体及作用方向，容易与“泄”混淆；宜用“我克者为耗”等表述配合白话解释，并说明仅凭这一关系不能判断喜用神。"
        }
      ],
      "reason": "未解释耗用关系及其方向，并把阴阳误列为必要条件，需要补充和修正。"
    },
    {
      "item": "i03",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "tradition",
          "detail": "五行“同类”指五行属性相同，不要求阴阳相同；例如甲木与乙木也属同类，阴阳差异用于进一步区分比肩、劫财。"
        },
        {
          "dimension": "plain_language",
          "detail": "未直接解释“同类”就是同属一种五行；宜补充这一定义，并将喜用神说明限定为“仅凭同类关系不能判断”。"
        }
      ],
      "reason": "同类关系不以阴阳为必要条件，现有文字也未提供清楚的白话定义。"
    },
    {
      "item": "i04",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "tradition",
          "detail": "“泄”由五行相生的作用方向确定，不以阴阳为成立条件；以某五行为主体时，其所生的五行会泄出主体之气。"
        },
        {
          "dimension": "plain_language",
          "detail": "未解释“泄”的参照方向。宜举例说明木生火时，火泄木之气，并提示“泄”不天然代表不利，不能仅据此判断喜用神。"
        }
      ],
      "reason": "需要纠正阴阳条件并解释泄出的方向，避免用户将“泄”直接理解为坏事。"
    },
    {
      "item": "i05",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "tradition",
          "detail": "五行相克关系由五行属性确定，不以阴阳为成立条件；阴阳可用于进一步区分十神，但不改变基本相克关系。"
        },
        {
          "dimension": "plain_language",
          "detail": "未解释“克”是制约、约束关系，如木克土；若与“耗”并列使用，还应明确主体及“克我”“我克”的区别，并说明相克不等于灾祸。"
        }
      ],
      "reason": "主题方向保持中性是合理的，但相克的判定条件与具体含义需要修正、补全。"
    }
  ]
}
